_onItemsModified(aItems) {
  if (this._listener) {
    try {
      this._listener.onItemsModified(aItems, this);
    } catch (ex) {
      LOG.error(
        "caught exception from listener in onItemsModified: " +
          ex.fileName +
          ":" +
          ex.lineNumber +
          ": " +
          ex
      );
    }
  }
